import json
import re

file_path = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/bec74516-02fc-48dc-b202-55e78d0e17cf.jsonld'

ORCID_REGEX = re.compile(r"\b(\d{4}-\d{4}-\d{4}-\d{3}[0-9X])\b")

def extract_orcids(data):
    found = set()
    def walk(o):
        if isinstance(o, dict):
            for k, v in o.items():
                if isinstance(v, str):
                    if 'orcid.org' in v:
                        m = ORCID_REGEX.search(v)
                        if m:
                            found.add(m.group(1))
                elif isinstance(v, (dict, list)):
                    walk(v)
        elif isinstance(o, list):
            for item in o:
                walk(item)
    walk(data)
    return sorted(found)

with open(file_path, 'r', encoding='utf-8') as f:
    data = json.load(f)

orcids = extract_orcids(data)
print('ORCIDs:', orcids)
```

I will use the ORCID public API to retrieve works and count pre-2020 entries. We'll access the record endpoint and navigate to activities-summary > works.

