import requests

orcids = ['0000-0003-0396-0333', '0000-0001-6102-7846', '0000-0002-1053-2030', '0000-0002-2605-6569', '0000-0002-0209-2784']

HEADERS = {'Accept': 'application/json'}

def safe_year(summary):
    pd = summary.get('publication-date') or {}
    y = (pd.get('year') or {}).get('value')
    try:
        return int(y) if y is not None else None
    except Exception:
        return None

def count_pre_2020(orcid):
    url = f'https://pub.orcid.org/v3.0/{orcid}/record'
    r = requests.get(url, headers=HEADERS, timeout=15)
    r.raise_for_status()
    rec = r.json()
    acts = rec.get('activities-summary', {})
    works = (acts.get('works') or {}).get('group', [])
    cnt = 0
    for g in works:
        for s in g.get('work-summary', []):
            y = safe_year(s)
            if y is not None and y < 2020:
                cnt += 1
    return cnt

results = {}
for oid in orcids:
    try:
        results[oid] = count_pre_2020(oid)
    except Exception as e:
        results[oid] = None
        print(f'Error for {oid}: {e}')

print('Pre-2020 counts:', results)
