import json
import requests

file_path = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/bec74516-02fc-48dc-b202-55e78d0e17cf.jsonld'

with open(file_path, 'r', encoding='utf-8') as f:
    data = json.load(f)

# Restrictive extraction: only identifiers explicitly listed under keys named 'identifier'
orcids = set()

def walk(o):
    if isinstance(o, dict):
        for k, v in o.items():
            if k == 'identifier' and isinstance(v, (list, dict)):
                items = v if isinstance(v, list) else [v]
                for it in items:
                    # assume structured identifier with 'scheme' and 'value'
                    if isinstance(it, dict) and str(it.get('scheme', '')).lower().startswith('orcid'):
                        val = it.get('value')
                        if isinstance(val, str):
                            orcids.add(val)
            elif isinstance(v, (dict, list)):
                walk(v)
    elif isinstance(o, list):
        for i in o:
            walk(i)

walk(data)
orcids = sorted(orcids)
print('Strict ORCIDs:', orcids)

HEADERS = {'Accept': 'application/json'}

def count_pre_2020(orcid):
    url = f'https://pub.orcid.org/v3.0/{orcid}/works'
    r = requests.get(url, headers=HEADERS, timeout=15)
    r.raise_for_status()
    w = r.json()
    cnt = 0
    for g in w.get('group', []):
        for s in g.get('work-summary', []):
            pd = s.get('publication-date') or {}
            y = (pd.get('year') or {}).get('value')
            try:
                if y and int(y) < 2020:
                    cnt += 1
            except Exception:
                pass
    return cnt

results = {}
for oid in orcids:
    try:
        results[oid] = count_pre_2020(oid)
    except Exception as e:
        results[oid] = None
        print('Error:', oid, e)

print('Counts (strict identifiers only):', results)
